def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_d = 0
    my_d = 0
    recent_d = 0
    unprov_d = 0
    punish_d = 0
    forgive_d = 0

    start = n - 10 if n > 10 else 0
    for i in range(n):
        a, b = history[i]
        if b == 'D':
            opp_d += 1
            if i >= start:
                recent_d += 1
        if a == 'D':
            my_d += 1

    if n >= 2:
        for i in range(1, n):
            prev_my = history[i - 1][0]
            cur_opp = history[i][1]
            if prev_my == 'C':
                if cur_opp == 'D':
                    unprov_d += 1
            else:
                if cur_opp == 'D':
                    punish_d += 1
                else:
                    forgive_d += 1

    if opp_d >= 4 and (opp_d * 2 >= n or recent_d >= 6):
        return 'D'
    if recent_d >= 7:
        return 'D'
    if unprov_d >= 4 and (unprov_d * 2 >= n or recent_d >= 5):
        return 'D'

    if opp_last == 'D':
        if n >= 2 and history[-2][1] == 'D':
            return 'D'

        if my_last == 'D':
            if recent_d <= 1 and opp_d <= max(3, n // 3):
                return 'C'

        provoked = n >= 2 and history[-2][0] == 'D'
        if provoked:
            if opp_d <= n // 3 and recent_d <= 3:
                return 'C'
            if forgive_d > punish_d:
                return 'C'
            return 'D'

        return 'D'

    if n >= 96:
        if my_last == 'C' and my_d > opp_d and punish_d == 0 and recent_d == 0 and opp_d <= max(1, n // 8):
            return 'D'
        if recent_d >= 2 or opp_d >= n // 2:
            return 'D'
        return 'C'

    if my_last == 'C' and n >= 20 and punish_d == 0 and recent_d == 0 and opp_d <= n // 8:
        if my_d == 0:
            return 'D'
        if my_d > opp_d and my_d * 4 < n:
            return 'D'

    return 'C'
